questions.prompt:
What number does this program print?

```cpp
#include <iostream>
using namespace std;

class Counter {
private:
    int value;

public:
    Counter() {
        value = 0;
    }

    void add(int n) {
        if (n > 0) {
            value += n;
        }
    }

    int get() {
        return value;
    }
};

int main() {
    Counter a, b;
    a.add(5);
    a.add(-2);
    b.add(3);
    a.add(4);
    cout << a.get() + b.get() << endl;
    return 0;
}
```

questions.marking_guide:
1 mark: `owner` and `battery` are declared under `private:`. 1 mark: a constructor with the class's name, no return type, and two parameters that set both attributes. 1 mark: `charge()` adds only a positive amount. 1 mark: `charge()` keeps the battery at 100 or below. 1 mark: `getBattery()` returns the battery, and `main()` creates the object correctly, e.g. `Phone p("Keza", 40); p.charge(30);`.

Example answer:

```cpp
#include <iostream>
#include <string>
using namespace std;

class Phone {
private:
    string owner;
    int battery;  // percent

public:
    Phone(string o, int b) {
        owner = o;
        battery = b;
    }

    void charge(int amount) {
        if (amount > 0) {
            battery += amount;
            if (battery > 100) {
                battery = 100;
            }
        }
    }

    int getBattery() {
        return battery;
    }
};

int main() {
    Phone p("Keza", 40);
    p.charge(30);
    cout << p.getBattery() << endl;
    return 0;
}
```

The example prints 70. Accept other correct ways to keep the battery at 100 or below, such as `battery = min(battery + amount, 100);`. Do not award the class marks if the class does not end with `};`.
